{"command":"cat <<'EOF' > lsp_client.py
import subprocess
import json
import sys
import threading

def read_stderr(p):
    for line in p.stderr:
        print(f"STDERR: {line.decode().strip()}", file=sys.stderr)

def send_request(p, method, params, id):
    req = {
        "jsonrpc": "2.0",
        "id": id,
        "method": method,
        "params": params
    }
    msg = json.dumps(req)
    content = f"Content-Length: {len(msg)}\r\n\r\n{msg}"
    p.stdin.write(content.encode())
    p.stdin.flush()

def read_response(p):
    while True:
        line = p.stdout.readline().decode()
        if not line:
            return None
        if line.startswith("Content-Length:"):
            content_length = int(line.split(":")[1].strip())
            p.stdout.readline() # \r\n
            msg = p.stdout.read(content_length).decode()
            res = json.loads(msg)
            if "id" in res:
                return res
            else:
                print(f"NOTIFICATION: {res['method']}", file=sys.stderr)

p = subprocess.Popen(['./executable', '--stdio'], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
t = threading.Thread(target=read_stderr, args=(p,))
t.daemon = True
t.start()

send_request(p, "initialize", {
    "processId": None,
    "rootUri": "file:///workspace/test-project",
    "capabilities": {}
}, 1)
print("Initialize Response:", json.dumps(read_response(p), indent=2))

send_request(p, "initialized", {}, None) # Not actually a request but a notification

send_request(p, "textDocument/didOpen", {
    "textDocument": {
        "uri": "file:///workspace/test-project/src/main.rs",
        "languageId": "rust",
        "version": 1,
        "text": open("test-project/src/main.rs").read()
    }
}, None)

send_request(p, "textDocument/hover", {
    "textDocument": {"uri": "file:///workspace/test-project/src/main.rs"},
    "position": {"line": 2, "character": 9}
}, 2)
print("Hover Response:", json.dumps(read_response(p), indent=2))

p.terminate()
EOF
python3 lsp_client.py
"}

