#[derive(Parser)]
#[command(name = "rustowl", version = "1.0.0-rc.1")]
struct Cli {
    #[arg(long)]
    stdio: bool,

    #[arg(short, long, action = clap::ArgAction::Count)]
    quiet: u8,

    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand)]
