fn main() {
    let args: Vec<String> = env::args().collect();

    if args.iter().any(|arg| arg == "-V" || arg == "--version") {
        println!("RustOwl v1.0.0-rc.1");
        return;
    }

    if args.iter().any(|arg| arg == "--stdio") {
        eprintln!("RustOwl v1.0.0-rc.1");
        eprintln!("This is an LSP server. You can use --help flag to show help.");
        run_lsp();
        return;
    }

    if args.len() < 2 || args.iter().any(|arg| arg == "-h" || arg == "--help") {
        if args.len() > 1 {
            match args[1].as_str() {
                "check" => print_check_help(),
                "clean" => print_clean_help(),
                "toolchain" => {
                    if args.len() > 2 {
                        match args[2].as_str() {
                            "install" => print_toolchain_install_help(),
                            "uninstall" => print_toolchain_uninstall_help(),
                            _ => print_toolchain_help(),
                        }
                    } else {
                        print_toolchain_help()
                    }
                },
                "completions" => print_completions_help(),
                _ => print_main_help(),
            }
        } else {
            println!("RustOwl v1.0.0-rc.1");
            println!("This is an LSP server. You can use --help flag to show help.");
        }
        return;
    }

    match args[1].as_str() {
        "check" => handle_check(&args[2..]),
        "clean" => handle_clean(),
        "toolchain" => handle_toolchain(&args[2..]),
        "completions" => handle_completions(&args[2..]),
        "help" => {
            if args.len() > 2 {
                 // handle help subcommand
