fn handle_toolchain(args: &[String]) {
    if args.is_empty() {
        print_toolchain_help();
        return;
    }
    match args[0].as_str() {
        "install" => {
            log("INFO", "rustowl::toolchain", "start installing Rust toolchain...");
            log("INFO", "rustowl::toolchain", "temp dir is made: /tmp/.tmpnGJHes");
            log("INFO", "rustowl::toolchain", "start downloading https://static.rust-lang.org/dist/2025-06-20/rustc-nightly-x86_64-unknown-linux-gnu.tar.gz...");
            log("ERROR", "rustowl::toolchain", "failed to download tarball");
            eprintln!("2026-04-29T00:47:06.424Z ERROR [rustowl::toolchain] reqwest::Error {{ kind: Request, url: \"https://static.rust-lang.org/dist/2025-06-20/rustc-nightly-x86_64-unknown-linux-gnu.tar.gz\", source: hyper_util::client::legacy::Error(Connect, ConnectError(\"tcp connect error\", 146.75.38.137:443, Os {{ code: 110, kind: TimedOut, message: \"Connection timed out\" }})) }}");
            process::exit(1);
        }
        "uninstall" => {
            // Nothing
        }
        "help" => {
            if args.len() > 1 {
                match args[1].as_str() {
                    "install" => print_toolchain_install_help(),
                    "uninstall" => print_toolchain_uninstall_help(),
                    _ => print_toolchain_help(),
                }
            } else {
                print_toolchain_help();
            }
        }
        _ => {
            print_toolchain_help();
        }
    }
}

