fn log(level: &str, target: &str, msg: &str) {
    let now = "2026-04-29T00:46:36.286Z";
    eprintln!("{} {} [{}] {}", now, level, target, msg);
}

fn run_lsp() {
    let stdin = io::stdin();
    let mut reader = stdin.lock();
    loop {
        let mut line = String::new();
        if reader.read_line(&mut line).unwrap() == 0 {
            break;
        }
        if line.starts_with("Content-Length:") {
            let len: usize = line["Content-Length:".len()..].trim().parse().unwrap();
            let mut empty_line = String::new();
            reader.read_line(&mut empty_line).unwrap(); // skip \r\n
            let mut body = vec![0u8; len];
            reader.read_exact(&mut body).unwrap();
            let body_str = String::from_utf8_lossy(&body);

            if body_str.contains("\"method\":\"initialize\"") {
                let id = find_id(&body_str);
                let response = format!(
                    r#"{{"jsonrpc":"2.0","result":{{"capabilities":{{"textDocumentSync":{{"change":2,"openClose":true,"save":true}},"workspace":{{"workspaceFolders":{{"changeNotifications":true,"supported":true}}}}}}}},"id":{}}}"#,
                    id
                );
                send_response(&response);
            } else if body_str.contains("\"method\":\"initialized\"") {
                // Ignore
            } else if body_str.contains("\"method\":\"textDocument/didOpen\"") {
                eprintln!("2026-04-29T00:48:19.124Z WARN  [rustowl::toolchain] cargo not found; fallback");
                eprintln!("2026-04-29T00:48:19.148Z WARN  [rustowl::lsp::analyze] Invalid analysis target: /workspace/test-project");
            } else if body_str.contains("\"id\":") {
                 let id = find_id(&body_str);
                 let method = find_method(&body_str);
                 let response = format!(
                     r#"{{"jsonrpc":"2.0","error":{{"code":-32601,"message":"Method not found","data":"{}"}},"id":{}}}"#,
                     method, id
                 );
                 send_response(&response);
            }
        }
    }
}

fn find_id(body: &str) -> String {
    if let Some(pos) = body.find("\"id\":") {
        let rest = &body[pos + 5..].trim();
        let end = rest.find(|c: char| !c.is_numeric() && c != 'n' && c != 'u' && c != 'l').unwrap_or(rest.len());
        rest[..end].to_string()
    } else {
        "null".to_string()
    }
}

fn find_method(body: &str) -> String {
    if let Some(pos) = body.find("\"method\":\"") {
        let rest = &body[pos + 10..];
        let end = rest.find('"').unwrap_or(rest.len());
        rest[..end].to_string()
    } else {
        "".to_string()
    }
}

fn send_response(res: &str) {
    let stdout = io::stdout();
    let mut writer = stdout.lock();
    write!(writer, "Content-Length: {}\r\n\r\n{}", res.len(), res).unwrap();
    writer.flush().unwrap();
}
